def serves(row: dict, *, cls: str, market: str, method: str, years: float = 1.0,
           delisted: bool = False, pit: bool = False, redistribute: bool = False,
           store: bool = False, key_ok: bool = True) -> str:
    """"" if the source serves the request, else the flag that refuses it."""
    if method not in row["serves"]:
        return "method"
    if cls not in row["classes"]:
        return "asset_class"
    if market not in row["markets"]:
        return "market"
    if delisted and not row["delisted"]:
        return "delisted"
    if pit and not row["pit"]:
        return "point_in_time"
    if redistribute and row["redistribution"] == "prohibited":
        return "redistribution"
    if store and row["cache"] == "no-persist":
        return "cache"
    if not key_ok and row["key"]:
        return "key"
    if not row["reachable"]:
        return "unreachable"
    if row["history"] is not None and years > row["history"]:
        return "history"
    return ""


def answer(**kw) -> tuple[list[str], dict[str, str]]:
    """(sources that serve it, {source: refusing flag})."""
    ok, refused = [], {}
    for name, row in sorted(SNAPSHOT.items()):
        flag = serves(row, **kw)
        if flag:
            refused[name] = flag
        else:
            ok.append(name)
    return ok, refused


def cross_check() -> dict | None:
    """Compare the snapshot above against the live Declarations, field by field.

    Returns None when the generated package is not importable, so this script still runs
    on a bare install; returns {"checked": n, "drift": [...]} otherwise.
    """
    try:
        from fin_skills.data import declare                            # noqa: PLC0415
        from fin_skills.data.advise import COVERAGE                    # noqa: PLC0415
    except ImportError:
        return None
    drift: list[str] = []
    live = {d.name: d for d in declare.declarations()}
    if set(live) != set(SNAPSHOT):
        drift.append(f"registry has {sorted(set(live) ^ set(SNAPSHOT))} that the "
                     f"snapshot does not, or the reverse")
    for name, row in sorted(SNAPSHOT.items()):
        d = live.get(name)
        if d is None:
            continue
        for label, mine, theirs in (
                ("delisted", row["delisted"], d.includes_delisted),
                ("pit", row["pit"], d.point_in_time),
                ("redistribution", row["redistribution"], d.redistribution),
                ("key", row["key"], d.requires_key),
                ("cache", row["cache"], d.cache_policy)):
            if mine != theirs:
                drift.append(f"{name}.{label}: snapshot {mine!r} != declaration {theirs!r}")
        cov = COVERAGE.get(name)
        if cov is None:
            continue
        for label, mine, theirs in (
                ("classes", set(row["classes"]), set(cov.asset_classes)),
                ("markets", set(row["markets"]), set(cov.markets)),
                ("serves", set(row["serves"]), set(cov.serves)),
                ("history", row["history"], cov.max_history_years),
                ("reachable", row["reachable"], cov.reachable)):
            if mine != theirs:
                drift.append(f"{name}.{label}: snapshot {mine!r} != coverage {theirs!r}")
    return {"checked": len(SNAPSHOT), "drift": drift}


def rule(title: str) -> None:
    print("\n" + title)
    print(SEP)


